def page(pid: str, rows: str | None = None, price: str | None = None, desc: str | None = None) -> str:
    g = globals()
    return (g[f"P{pid}_BODY"] + g[f"P{pid}_H1"] + (price if price is not None else g[f"P{pid}_PRICE"])
            + "<ul>" + (rows if rows is not None else g[f"P{pid}_ROWS"]) + "</ul>"
            + g[f"P{pid}_FEATURES"] + (desc if desc is not None else g[f"P{pid}_DESC"])
            + g[f"P{pid}_ZOOM"] + "</body></html>")


# ── 1/2. identity and the swapped location rows ──────────────────────────────────────────────────
def test_identity_and_location():
    row, cat, why = L.map_listing(URL, page("9543"))
    assert why == "" and cat == "residential"
    assert row["ad_number"] == "LCP9543" and row["listing_url"] == URL and row["source"] == "LivingCompound"
    assert (row["city_ar"], row["city_id"], row["region_id"]) == ("جدة", 2, 200), "Province/State IS the city"
    assert row["district_ar"] == "حي النهضة" and row["neighborhood"] == "Al Nahdah", "City/Town IS the district"
    assert row["title"] == "3BR Duplex Villa with Pool | Al Nahada"
    assert row["property_type"] == "Villa" and row["transaction_type"] == "Rent"


def test_an_unattested_district_stays_null_with_the_raw_text_kept():
    row, _, _ = L.map_listing(URL, page("9543", rows=P9543_ROWS.replace("Al Nahdah", "Al Marjan")))
    assert row["district_ar"] is None and row["neighborhood"] == "Al Marjan"


# ── 3. price and period ──────────────────────────────────────────────────────────────────────────
def test_year_postfix_is_annual_and_the_figure_is_verbatim():
    row, _, _ = L.map_listing(URL, page("9543"))
    assert row["price_annual"] == 85000 and row["rent_period"] == "annual"
    assert row["price_evidence"]["raw"] == "SAR 85,000 / Year" and row["price_evidence"]["kind"] == "annual"
    assert "price_total" not in row


def test_month_postfix_is_monthly_times_twelve():
    row, _, why = L.map_listing(URL, page("9746"))
    assert why == "" and row["rent_period"] == "monthly" and row["price_annual"] == 60000
    assert row["price_evidence"]["raw"] == "SAR 5,000 / Monthly" and row["district_ar"] == "حي الرويس"


def test_no_postfix_means_no_period_and_an_unconverted_figure():
    row, _, why = L.map_listing(URL, page("9927"))
    assert why == "" and row["price_annual"] == 185000 and row["rent_period"] is None
    assert row["price_evidence"]["kind"] == "total"
    assert row["property_type"] == "Villa", "«Compound , Compound Villa , Villa» names one canon type"


def test_a_stated_but_unsupported_postfix_is_nulled_never_parked_as_annual():
    """Regression (review 2026-09-24): a postfix that IS present but states a period the schema
    has no bucket for (a hypothetical '/ Day', same class as يومي/أسبوعي/نصف سنوي) must NOT fall
    into the same branch as a genuinely SILENT price (post 9927, no postfix element at all). Not
    observed on the live 19-listing walk today (only '/ Year', '/ Monthly' and none exist) — this
    pins the latent defect the reviewer found by construction, mirroring normalize's own shared
    rent_period_and_annual() (None, None) rule for an unrecognized period token."""
    row, _, why = L.map_listing(URL, page("9543", price=P9543_PRICE.replace("/ Year", "/ Day")))
    assert why == "" and row["rent_period"] is None and row["price_annual"] is None
    assert row["price_evidence"]["stored"] is None


def test_for_sale_stores_a_total_and_no_period():
    """No sale listing was live on capture day; «For Rent» is replaced by «For Sale» inside the
    verbatim status row to prove the branch. transaction_type is the fleet's CANONICAL value
    (CANONICAL = {"Buy","Rent"}) — regression: this scraper originally wrote the literal "Sale",
    which is not a value any downstream reader (search sync, the AF eligibility predicate) treats
    as a valid deal, so every one of this platform's for-sale rows would have been silently
    quarantined out of search on day one."""
    row, _, why = L.map_listing(URL, page("9543", rows=P9543_ROWS.replace("For Rent", "For Sale")))
    assert why == "" and row["transaction_type"] == "Buy" and row["price_total"] == 85000
    assert "price_annual" not in row and "rent_period" not in row


