# ── 7. removal oracle ────────────────────────────────────────────────────────────────────────────
def test_the_post_signal_and_the_shared_law(monkeypatch):
    sig = L._post_signal("9543")
    assert sig(404, "", False) == "gone"
    assert sig(200, page("9543"), True) == "live"
    assert sig(200, page("9746"), True) is None, "landed on a different post"
    assert sig(200, page("9543", rows=P9543_ROWS.replace(">Premium<", ">Rented<")), True) == "gone"
    assert sig(403, page("9543"), False) is None
    served = {"status": 403, "body": page("9543")}
    monkeypatch.setattr(http_liveness.LivenessProbe, "fetch", lambda self, url: (served["status"], served["body"], True))
    monkeypatch.setattr(http_liveness, "time", types.SimpleNamespace(sleep=lambda *_: None))
    verify = L._make_verify_gone(None)
    assert verify("LCP9543")[0] == "unknown"
    served["status"] = 404
    verdict, why = verify("LCP9543")
    assert verdict == "unknown" and "no row from this run" in why
    served["status"], served["body"] = 200, page("9543")
    assert L._make_verify_gone({"ad_number": "LCP9543"})("LCP9543")[0] == "live"
    assert verify("LCPabc")[0] == "unknown"


# ── 8. main() ────────────────────────────────────────────────────────────────────────────────────
class _FakeResp:
    def __init__(self, status, text):
        self.status_code, self.text = status, text


def _wire(monkeypatch, pages: dict, argv: list[str]):
    sitemap = "<urlset><loc>https://livingcompound.com/property/</loc>" + "".join(f"<loc>{u}</loc>" for u in pages) + "</urlset>"

    class _S:
        def get(self, url, timeout=0):
            if url.endswith("property-sitemap.xml"):
                return _FakeResp(200, sitemap)
            got = pages[url]
            if isinstance(got, Exception):
                raise got
            return _FakeResp(*got)

    calls: dict = {"end_run": [], "batch": [], "prune": [], "retire": []}
    monkeypatch.setattr(L, "session", lambda: _S())
    monkeypatch.setattr(L, "time", types.SimpleNamespace(sleep=lambda *_: None))
    monkeypatch.setattr(L.db, "begin_run", lambda p: 7)
    monkeypatch.setattr(L.db, "end_run", lambda run_id, **kw: (calls["end_run"].append(kw), True)[1])
    monkeypatch.setattr(L.db, "_wasalt_batch", lambda table, rows: calls["batch"].append((table, len(rows))))
    monkeypatch.setattr(L.db, "retire_superseded_siblings", lambda **kw: calls["retire"].append(kw) or 0)
    monkeypatch.setattr(L.db, "prune_unseen", lambda table, seen, **kw: calls["prune"].append((table, set(seen))) or 0)
    monkeypatch.setattr(L.db, "mark_direct_alive", lambda row, *, oracle: row)
    monkeypatch.setattr("sys.argv", ["run.py", *argv])
    return calls


def test_main_writes_the_tally_into_end_run_notes_and_prunes_after_a_complete_walk(monkeypatch):
    pages = {URL: (200, page("9543")), "https://livingcompound.com/property/b/": (200, page("9951")),
             "https://livingcompound.com/property/c/": (404, "gone")}
    calls = _wire(monkeypatch, pages, [])
    assert L.main() == 0
    kw = calls["end_run"][0]
    assert kw["rows_seen"] == 3 and kw["rows_upserted"] == 1 and kw["ok"] is True
    assert "deal_unstatedx1" in kw["notes"] and "http_404x1" in kw["notes"]
    assert kw["check_tables"] == ["livingcompound_residential_listings", "livingcompound_commercial_listings"]
    assert calls["batch"] == [("livingcompound_residential_listings", 1), ("livingcompound_commercial_listings", 0)]
    assert calls["retire"][0]["res_ads"] == {"LCP9543"} and calls["retire"][0]["com_ads"] == set()
    assert [p[0] for p in calls["prune"]] == ["livingcompound_residential_listings", "livingcompound_commercial_listings"]


def test_main_never_prunes_after_an_incomplete_walk_and_dry_run_writes_nothing(monkeypatch):
    calls = _wire(monkeypatch, {URL: (200, page("9543")), "https://livingcompound.com/property/x/": RuntimeError("reset")}, [])
    assert L.main() == 0 and calls["prune"] == [] and "unreachablex1" in calls["end_run"][0]["notes"]
    calls = _wire(monkeypatch, {URL: (200, page("9543"))}, ["--dry-run"])
    assert L.main() == 0 and calls["batch"] == [] and calls["end_run"] == []
